-- pintopets_account_settings: tenant-scoped rows behind /account-settings (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_account_settings (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            user_uuid UUID NOT NULL,
            totp_secret_enc TEXT,
            totp_enabled_at TIMESTAMPTZ,
            require_code_at_sign_in BOOLEAN NOT NULL DEFAULT FALSE,
            recovery_codes JSONB,
            failed_attempts INTEGER NOT NULL DEFAULT 0,
            locked_until TIMESTAMPTZ,
            consent_ai_learning BOOLEAN,
            consent_ai_learning_at TIMESTAMPTZ,
            consent_marketing BOOLEAN,
            consent_marketing_at TIMESTAMPTZ,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_account_settings_namespace ON pintopets_account_settings (namespace_id, id DESC)")
    db.query("CREATE UNIQUE INDEX IF NOT EXISTS uq_pintopets_account_settings_user ON pintopets_account_settings (namespace_id, user_uuid)")
end
